#!/usr/bin/env python3
"""
Source-of-truth question authoring script for Rukhsa (UAE Driving Test).

Run this once (or whenever content changes) to (re)generate the per-category
JSON files under rukhsa/content/bank/. English ("en") and Arabic ("ar") text
is authored by hand below. Other 8 languages are NOT authored here manually -
build_bundle.py fills them with an English fallback + translationStatus:
"pending" marker, so it is always clear which text is a verified translation
and which is a placeholder.

Facts that are commonly cited for the UAE RTA theory test but that we are not
fully confident about (exact fine amounts, exact black-point counts, etc.)
are marked needsVerification: true so they are easy to filter out and check
against the official RTA Light Motor Vehicle Driver's Handbook before this
content is treated as authoritative.
"""
import json
import os

