def main():
    os.makedirs(OUT_DIR, exist_ok=True)
    total = 0
    for category, questions in BANK.items():
        for q in questions:
            q.setdefault("needsVerification", False)
            q["category"] = category
        path = os.path.join(OUT_DIR, f"{category}.json")
        with open(path, "w", encoding="utf-8") as f:
            json.dump({"category": category, "questions": questions}, f, ensure_ascii=False, indent=2)
        total += len(questions)
        print(f"wrote {len(questions):2d} questions -> {path}")
    print(f"TOTAL questions authored: {total}")

if __name__ == "__main__":
    main()
